mapper.select:
SELECT * FROM spectra_core.file_asset
WHERE status IN ('READY', 'DELETING') AND deleted IS NULL
  AND orphaned_at IS NOT NULL AND next_cleanup_at IS NOT NULL AND next_cleanup_at <= #{now}
ORDER BY next_cleanup_at
LIMIT #{limit}
FOR UPDATE SKIP LOCKED

SELECT a.* FROM spectra_core.file_asset a
WHERE a.status = 'READY' AND a.deleted IS NULL
  AND a.orphaned_at IS NULL AND a.completed_at <= #{cutoff}
  AND NOT EXISTS (
      SELECT 1 FROM spectra_core.file_reference r
      WHERE r.file_asset_id = a.id AND r.deleted IS NULL
  )
ORDER BY a.completed_at
LIMIT #{limit}
FOR UPDATE SKIP LOCKED
